// A message from the demo page's chat becomes the common inbound message. The page keeps a random
// session id; each message carries its own id, so a retried POST is stored once.
const profile = $('Config').first().json.profile;
const b = $('Chat message').first().json.body ?? {};
const session = String(b.session ?? '');
const id = String(b.message_id ?? '');
const text = String(b.text ?? '').trim();
const valid = /^[A-Za-z0-9-]{16,64}$/.test(session) && /^[A-Za-z0-9-]{8,64}$/.test(id) && text.length > 0 && text.length <= 2000;
if (!valid) return [{ json: { valid: false } }];
return [{ json: {
  valid: true,
  profile,
  channel: 'web_chat',
  external_user_id: session,
  external_message_id: id,
  sent_at: new Date().toISOString(),
  text,
  attachments: [],
  sender: { display_name: null, username: null, phone: null, email: null },
  address: { session },
} }];
